/** Native surface/animation regression using one held synthetic source, never real API or news. */
public final class SurfaceSmoke extends Instrumentation {
  private Activity activity;private String checkpoint="start";private final int[] width=new int[4];
  @Override public void onCreate(Bundle args){super.onCreate(args);start();}
  private static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
  private Object get(String field){try{Field f=activity.getClass().getDeclaredField(field);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new RuntimeException(e);}}
  private void set(String field,Object value){try{Field f=activity.getClass().getDeclaredField(field);f.setAccessible(true);f.set(activity,value);}catch(Exception e){throw new RuntimeException(e);}}
  private Object call(String name,Class<?>[] types,Object...args){try{Method m=activity.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new RuntimeException(e);}}
  private void main(Runnable action){Throwable[] failure={null};runOnMainSync(()->{try{action.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new RuntimeException(failure[0]);}
  private void waitUntil(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){boolean[] ready={false};main(()->ready[0]=condition.getAsBoolean());if(ready[0])return;SystemClock.sleep(20);}throw new AssertionError("Timeout at "+checkpoint);}
  private List<View> views(View view){List<View> out=new ArrayList<>();out.add(view);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)out.addAll(views(group.getChildAt(i)));}return out;}
  private TextView exact(String value){for(View view:views((View)get("body")))if(view instanceof TextView&&value.contentEquals(((TextView)view).getText()))return (TextView)view;throw new AssertionError("Missing "+value);}
  private void render(){call("render",new Class<?>[]{boolean.class},false);}
  private void page(int page){main(()->{set("tab",page);call("drawNav",new Class<?>[0]);render();});SystemClock.sleep(250);}
  private void theme(String mode){main(()->{((NewsState)get("savedState")).themeMode=mode;call("applyTheme",new Class<?>[0]);call("chrome",new Class<?>[0]);render();});SystemClock.sleep(250);}
  private void shot(String name)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand("screencap -p /data/local/tmp/surface420-"+name+".png"))){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
  private boolean visibleText(String value){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root==null)return false;for(android.view.accessibility.AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(value))if(value.contentEquals(n.getText()))return true;return false;}
  @Override public void onStart(){Bundle report=new Bundle();CountDownLatch gate=new CountDownLatch(1);
    try{
      new AiVault(getTargetContext().getFilesDir()).forget();activity=startActivitySync(new Intent(Intent.ACTION_MAIN).setClassName("cn.yilan.news","cn.yilan.news.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitUntil(()->!((AiCoordinator)get("aiService")).loading);
      NewsState state=(NewsState)get("savedState");String config=(String)call("asset",new Class<?>[]{String.class},"sources.json");NewsEngine engine=new NewsEngine(config,(source,url)->{if(!gate.await(20,TimeUnit.SECONDS))throw new IOException("Synthetic gate timeout");return "<rss><channel><item><title>新的界面验证新闻</title><link>https://www.ithome.com/0/surface-420.htm</link><pubDate>Fri, 13 Nov 2026 01:00:00 GMT</pubDate></item></channel></rss>";});
      main(()->{set("engine",engine);state.snapshots.clear();state.favorites.clear();state.backgroundArt=true;state.motion=true;for(String id:state.sourceEnabled.keySet())state.sourceEnabled.put(id,id.equals("ithome"));try{for(String id:new String[]{"ithome","infoq-cn"}){Article a=NewsEngine.parse(engine.sourceMap.get(id),"<rss><channel><item><title>"+(id.equals("ithome")?"科技与城市的新消息，等待你来阅读":"模型与开发者工具的最新动态")+"</title><link>https://www.ithome.com/0/surface-"+id+".htm</link></item></channel></rss>",System.currentTimeMillis()).get(0);a.published=System.currentTimeMillis();Snapshot s=new Snapshot(id);s.items.add(a);s.fetched=System.currentTimeMillis();state.snapshots.put(id,s);state.sourceEnabled.put(id,true);if(id.equals("ithome"))state.favorites.add(a);}}catch(Exception e){throw new RuntimeException(e);}});
      checkpoint="settings peers";theme("day");page(3);main(()->{LinearLayout body=(LinearLayout)get("body");for(String heading:new String[]{"外观","AI 功能","缓存管理","消息来源"})check(exact(heading).getParent().getParent()==body,"Settings must have four peer sections");check(exact("接口与模型").isEnabled()&&!exact("与 AI 对话").isEnabled(),"Unconfigured AI has a prominent action without opening unconfigured chat");});shot("settings-day");main(()->((ScrollView)get("scroll")).smoothScrollTo(0,Math.round(330*activity.getResources().getDisplayMetrics().density)));SystemClock.sleep(350);shot("settings-actions");
      checkpoint="AI actions";main(()->exact("接口与模型").performClick());waitUntil(()->visibleText("API Key"));sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);main(()->{try{((AiCoordinator)get("aiService")).config=new AiClient.Config("https://example.com/v1","synthetic-surface-only","surface-model","surface-profile",true);}catch(Exception e){throw new RuntimeException(e);}render();exact("与 AI 对话").performClick();});waitUntil(()->visibleText("发送"));sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);main(()->{((AiCoordinator)get("aiService")).config=null;render();});
      checkpoint="cache action";main(()->exact("打开缓存日历").performClick());SystemClock.sleep(150);sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);
      checkpoint="settings appearance";main(()->{((ScrollView)get("scroll")).scrollTo(0,0);((Switch)exact("界面动效")).performClick();});check(!state.motion,"Motion toggle must persist in state");main(()->((Switch)exact("界面动效")).performClick());main(()->((Switch)exact("背景插画")).performClick());page(0);shot("news-flat");check(!state.backgroundArt,"Artwork toggle must persist in state");main(()->{state.backgroundArt=true;render();});SystemClock.sleep(200);shot("news-day");page(1);shot("ai-day");page(2);shot("saved-day");theme("night");page(0);shot("news-night");page(3);shot("settings-night");
      checkpoint="header enter";theme("day");page(0);main(()->{state.sourceEnabled.put("infoq-cn",false);state.snapshots.get("ithome").fetched=1;});main(()->{width[0]=((Button)get("refresh")).getWidth();((Button)get("refresh")).performClick();check(!((View)get("search")).isEnabled(),"Starting update releases search input");});SystemClock.sleep(70);main(()->width[1]=((Button)get("refresh")).getWidth());SystemClock.sleep(80);main(()->width[2]=((Button)get("refresh")).getWidth());waitUntil(()->!((ReaderUpdateTransition)get("updateTransition")).isAnimating());main(()->{width[3]=((Button)get("refresh")).getWidth();check(width[0]<width[1]&&width[1]<=width[2]&&width[2]<=width[3],"Update control must pass through intermediate widths");check(((View)get("search")).getVisibility()==View.GONE&&((Button)get("refresh")).getLayoutParams().width==-1,"Expanded final layout hides search");check(((ProgressBar)get("progress")).getProgress()==0,"Animation must not fake network progress");});shot("updating");
      checkpoint="phase changes";AiCoordinator ai=(AiCoordinator)get("aiService");main(()->{ai.running=true;ai.stage="生成汇报";ai.stageTotal=10;ai.stageDone=3;call("updateRefreshControls",new Class<?>[0]);check(((Button)get("refresh")).getText().toString().equals("正在生成汇报")&&((ProgressBar)get("progress")).getProgress()==3,"Phase label/progress must reflect work without a width restart");ai.stage="生成精选";ai.stageDone=7;call("updateRefreshControls",new Class<?>[0]);check(!((ReaderUpdateTransition)get("updateTransition")).isAnimating(),"Same working state must not restart layout animation");});gate.countDown();waitUntil(()->!(Boolean)get("busy"));main(()->{ai.running=false;call("updateRefreshControls",new Class<?>[0]);});SystemClock.sleep(80);main(()->check(((Button)get("refresh")).getWidth()<width[3],"Idle restoration also has intermediate widths"));waitUntil(()->!((ReaderUpdateTransition)get("updateTransition")).isAnimating());main(()->check(((View)get("search")).getVisibility()==View.VISIBLE&&!((View)get("search")).hasFocus()&&((Button)get("refresh")).getText().toString().equals("更新"),"Restored idle search must not regain focus"));
      checkpoint="interruption";main(()->{set("busy",true);call("updateRefreshControls",new Class<?>[0]);});SystemClock.sleep(80);main(()->{set("busy",false);call("updateRefreshControls",new Class<?>[0]);set("busy",true);call("updateRefreshControls",new Class<?>[0]);});waitUntil(()->!((ReaderUpdateTransition)get("updateTransition")).isAnimating());main(()->check(((View)get("search")).getVisibility()==View.GONE,"Interrupted morph must settle to the most recent target"));
      checkpoint="reduced motion";main(()->{state.motion=false;set("busy",false);call("updateRefreshControls",new Class<?>[0]);set("busy",true);call("updateRefreshControls",new Class<?>[0]);check(!((ReaderUpdateTransition)get("updateTransition")).isAnimating()&&!((android.animation.ValueAnimator)get("refreshSpin")).isStarted()&&((View)get("search")).getVisibility()==View.GONE,"Disabled motion snaps layout and stops decorative spinning");set("busy",false);call("updateRefreshControls",new Class<?>[0]);state.motion=true;call("saveNow",new Class<?>[0]);});
      report.putString("result","PASS");report.putString("surface","peer settings and actions; day/night artwork and flat mode; intermediate width morph/reverse/interruption; real phase progress; reduced motion and focus preservation");report.putString("widths",Arrays.toString(width));
    }catch(Throwable e){report.putString("result","FAIL");report.putString("error",checkpoint+": "+e.toString());report.putString("debugWidths",Arrays.toString(width));if(activity!=null)report.putString("motion",String.valueOf(((NewsState)get("savedState")).motion)+"/"+android.animation.ValueAnimator.areAnimatorsEnabled()+";foreground="+get("foreground"));}
    finally{gate.countDown();if(activity!=null)runOnMainSync(()->activity.finish());}finish("PASS".equals(report.getString("result"))?-1:1,report);
  }
}
